using System;using System.Linq;using System.IO;using System.Windows;using System.Windows.Controls;
namespace Touchfish {public partial class PanelWindow {
 public void PreviewSealedScope(string folder){previewRun=true;Directory.CreateDirectory(folder);int before=checks;if(VerificationRun.Visual){lanSealedMode=true;lanIsHost=true;sealedSession=new SealedSession(catalog,77861,matchRules.Supports);sealedView=sealedSession.View(0);ApplyTheme(true,true);ApplyMode(false);RenderSealed();Render(Path.Combine(folder,"sealed-class-normal.png"));SealedAction("class",sealedView.Classes[0]);SealedAction("open");Render(Path.Combine(folder,"sealed-pack-normal.png"));SealedAction("open-all");var columns=(Grid)sealedStage.Children.Cast<UIElement>().First(e=>Grid.GetRow(e)==2);var rows=(StackPanel)((ScrollViewer)columns.Children[0]).Content;var plus=rows.Children.OfType<Grid>().First().Children.OfType<Button>().Single(b=>b.Content.ToString()=="+");plus.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent));Check(sealedView.Deck.Values.Sum()==1,"Actual builder plus button adds an owned card");foreach(var entry in sealedView.Pool.Take(5).ToArray())if(sealedView.Deck.Values.Sum()<6)SealedAction("edit",entry.Key,1);VerifySealedPresentation(folder);Render(Path.Combine(folder,"sealed-build-normal.png"));ApplyMode(true);RenderSealed();Render(Path.Combine(folder,"sealed-build-minimal.png"));Check(Width==392&&Height==300&&sealedStage.ActualHeight==170,"Sealed builder fits fixed minimal window");ApplyMode(false);ResetSealed();HideSealed();}
  VerifySealedTcp();File.WriteAllText(Path.Combine(folder,"sealed-verification.txt"),"PASS "+(checks-before)+" checks; WPF="+VerificationRun.Visual+"; loopback TCP="+VerificationRun.Network+"; no real user data writes.");
 }
 void FillSealedUi(PanelWindow window){if(window.sealedView.Phase=="class"){window.SealedAction("class",window.sealedView.Classes[0]);if(!window.lanIsHost)PumpLan(()=>!window.lanWaiting,"Class choice acknowledged");}if(window.sealedView.Opened<18){window.SealedAction("open-all");if(!window.lanIsHost)PumpLan(()=>!window.lanWaiting,"Opening eighteen packs acknowledged");}foreach(var pair in window.sealedView.Pool.ToArray()){for(int n=window.sealedView.Deck.ContainsKey(pair.Key)?window.sealedView.Deck[pair.Key]:0;n<pair.Value&&window.sealedView.Deck.Values.Sum()<30;n++){window.SealedAction("edit",pair.Key,1);if(!window.lanIsHost)PumpLan(()=>!window.lanWaiting,"Private deck edit acknowledged");}}}
 void VerifySealedPresentation(string folder){
  FillSealedUi(this);UpdateLayout();PumpLan(()=>sealedScrolls.All(s=>s!=null&&s.IsLoaded),"Both sealed lists are loaded");sealedScrolls[0].ScrollToVerticalOffset(150);sealedScrolls[1].ScrollToVerticalOffset(70);UpdateLayout();double left=sealedScrolls[0].VerticalOffset,right=sealedScrolls[1].VerticalOffset;Check(left>0&&right>0,"Both lists can scroll independently");
  string remove=sealedView.Deck.Keys.First();SealedAction("edit",remove,-1);UpdateLayout();PumpLan(()=>Math.Abs(sealedScrolls[0].VerticalOffset-left)<1&&Math.Abs(sealedScrolls[1].VerticalOffset-right)<1,"Own removal preserves both scroll positions");
  var rows=(StackPanel)sealedScrolls[0].Content;var detail=rows.Children.OfType<Grid>().First().Children.OfType<Button>().First(b=>b.Content.ToString()=="…");detail.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent));UpdateLayout();PumpLan(()=>sealedDetailId!=null&&Math.Abs(sealedScrolls[0].VerticalOffset-left)<1,"Three-dot detail opens without jumping list");string inspected=sealedDetailId;Check(SealedCardDescription(catalog.Card(inspected)).Contains(catalog.Card(inspected).Text),"Detail includes full effect text");Render(Path.Combine(folder,"sealed-details-normal.png"));
  var previousList=sealedScrolls[0];sealedView=sealedSession.View(0);sealedView.OpponentOpened=18;RenderSealed();Check(Object.ReferenceEquals(previousList,sealedScrolls[0]),"Opponent-only update does not rebuild local card widgets");UpdateLayout();PumpLan(()=>sealedDetailId==inspected&&Math.Abs(sealedScrolls[0].VerticalOffset-left)<1&&Math.Abs(sealedScrolls[1].VerticalOffset-right)<1,"Opponent-only progress preserves scroll and opened details");sealedDetailId=null;RenderSealed();UpdateLayout();
 }
 void VerifySealedScrollTcp(PanelWindow guest){UpdateLayout();guest.UpdateLayout();PumpLan(()=>sealedScrolls[0].IsLoaded&&guest.sealedScrolls[0].IsLoaded,"Both peers' builder lists loaded");sealedScrolls[0].ScrollToVerticalOffset(140);guest.sealedScrolls[0].ScrollToVerticalOffset(130);UpdateLayout();guest.UpdateLayout();double hostOffset=sealedScrolls[0].VerticalOffset,guestOffset=guest.sealedScrolls[0].VerticalOffset;var hostList=sealedScrolls[0];string removed=guest.sealedView.Deck.Keys.First();guest.SealedAction("edit",removed,-1);PumpLan(()=>!guest.lanWaiting,"Guest removal acknowledged without losing scroll");guest.UpdateLayout();Check(Object.ReferenceEquals(hostList,sealedScrolls[0])&&Math.Abs(sealedScrolls[0].VerticalOffset-hostOffset)<1&&Math.Abs(guest.sealedScrolls[0].VerticalOffset-guestOffset)<1,"Real opponent edit keeps host widgets and both peers' scroll positions");guest.SealedAction("edit",removed,1);PumpLan(()=>!guest.lanWaiting,"Guest restores card after scroll check");}
 void VerifySealedTcp(){if(!VerificationRun.Network)return;LeaveLan();var guest=new PanelWindow(true){ShowInTaskbar=false,Opacity=0};guest.Show();try{lanPort.Text=FreeLanPort().ToString();lanModePicker.SelectedItem=((Choice[])lanModePicker.ItemsSource).First(c=>c.Key=="sealed");BeginLan(true);guest.lanModePicker.SelectedItem=((Choice[])guest.lanModePicker.ItemsSource).First(c=>c.Key=="sealed");guest.lanAddress.Text="127.0.0.1:"+lanPort.Text;guest.BeginLan(false);PumpLan(()=>sealedSession!=null&&guest.sealedView!=null,"Sealed peers complete handshake");
   SealedAction("class",sealedView.Classes[0]);SealedAction("open-all");PumpLan(()=>guest.sealedView.OpponentOpened==18,"Opponent receives opening progress");Check(guest.sealedView.Pool.Count==0&&guest.sealedView.LastPack.Length==0,"Opening progress does not leak opponent card pool or last pack");FillSealedUi(this);FillSealedUi(guest);VerifySealedScrollTcp(guest);var pool=String.Join(",",guest.sealedView.Pool.Select(p=>p.Key+":"+p.Value));SealedAction("confirm");guest.SealedAction("confirm");PumpLan(()=>lanReady&&guest.lanReady,"Both confirmed decks start sealed match");Check(match.Mode.Id=="sealed"&&guest.match.Mode.Id=="sealed"&&CanMulliganInput()&&guest.CanMulliganInput(),"Sealed initial state unlocks both mulligans");CheckMulliganCardClick(this,"Sealed host can select replacement");CheckMulliganCardClick(guest,"Sealed guest can select replacement");
   FinishArenaGameWithFireball(guest,0);PumpLan(()=>sealedSession.Round==2&&guest.sealedView.Round==2&&!guest.lanReady,"First result opens between-game rebuild");Check(pool==String.Join(",",guest.sealedView.Pool.Select(p=>p.Key+":"+p.Value))&&guest.sealedView.Opened==18,"Rebuild retains exactly the initial ninety cards without new packs");string removed=guest.sealedView.Deck.Keys.First();guest.SealedAction("edit",removed,-1);PumpLan(()=>!guest.lanWaiting,"Rebuild removal acknowledged");string added=guest.sealedView.Pool.Keys.First(id=>id!=removed&&(!guest.sealedView.Deck.ContainsKey(id)||guest.sealedView.Deck[id]<guest.sealedView.Pool[id]));guest.SealedAction("edit",added,1);PumpLan(()=>!guest.lanWaiting,"Rebuild addition acknowledged");guest.SealedAction("confirm");PumpLan(()=>!guest.lanWaiting,"Guest confirms rebuild");SealedAction("confirm");PumpLan(()=>lanReady&&guest.lanReady&&!guest.match.MulliganComplete,"Rebuilt decks start second game with fresh mulligan");Check(guest.lanArenaWins1==1&&guest.lanArenaGameNumber==2,"Series score and game number synchronize");FinishArenaGameWithFireball(guest,0);PumpLan(()=>sealedSession.SeriesWinner==1&&guest.lanArenaSeriesWinner==1,"Two wins finish sealed series");Check(sealedSession.Round==2&&sealedSession.Wins1==2,"Completed series does not need a third game");
  }finally{guest.LeaveLan();guest.Close();LeaveLan();}}
}}
